let drawbackMap: Map<string, number> | null = null;
let rodtepMap: Map<string, { uqc: string; rate: number }> | null = null;

function drawback(): Map<string, number> {
	if (!drawbackMap) {
		drawbackMap = new Map();
		for (const part of DRAWBACK_RAW.split('|')) {
			const i = part.indexOf(':');
			drawbackMap.set(part.slice(0, i), Number(part.slice(i + 1)));
		}
	}
	return drawbackMap;
}

function rodtep(): Map<string, { uqc: string; rate: number }> {
	if (!rodtepMap) {
		rodtepMap = new Map();
		for (const part of RODTEP_RAW.split('|')) {
			const [code, uqc, rate] = part.split(':');
			rodtepMap.set(code, { uqc, rate: Number(rate) });
		}
	}
	return rodtepMap;
}

export const normalizeRitc = (raw: string | number | null | undefined): string =>
	String(raw ?? '').replace(/\D/g, '');

export interface DrawbackEntry {
	/** Schedule serial with the `B` suffix, e.g. `940399B`. */
	schno: string;
	rate: number;
	/** Other serials under the same heading, for the review warning. */
	alternatives: string[];
	/** True when the residual "Others" entry was used rather than an exact match. */
	residual: boolean;
}

/**
 * Resolve a RITC against the drawback schedule.
 *
 * The schedule uses its own numbering, not tariff prefixes: within a heading, the
 * `99` entry is the residual "Others" line, which is where most tariff items land.
 * A specific sub-entry (say a "Handicraft/Artware of wood" line) is a classification
 * the exporter makes, so when the residual is used the caller is handed the other
 * candidates under that heading and warns rather than asserting.
 */
export function lookupDrawback(ritcRaw: string | number | null | undefined): DrawbackEntry | null {
	const ritc = normalizeRitc(ritcRaw);
	if (ritc.length < 4) return null;

	const table = drawback();
	const heading = ritc.slice(0, 4);
	const residualKey = heading + '99';
	const candidates = [ritc.slice(0, 8), residualKey, ritc.slice(0, 6), heading];

	for (const key of candidates) {
		if (!table.has(key)) continue;
		const alternatives: string[] = [];
		for (const serial of table.keys()) {
			if (serial !== key && serial.startsWith(heading) && serial.length > heading.length) {
				alternatives.push(serial + 'B');
			}
		}
		return {
			// "B" = the schedule's column B, "drawback when Cenvat facility has been availed".
			schno: key + 'B',
			rate: table.get(key)!,
			alternatives: alternatives.slice(0, 8),
			residual: key === residualKey
		};
	}
	return null;
}

export interface RodtepEntry {
	/** Statistical unit prescribed for the tariff item, e.g. `u` or `Kg`. */
	uqc: string;
	rate: number;
}

/** Exact 8-digit lookup only - RoDTEP eligibility is per tariff item. */
export function lookupRodtep(ritcRaw: string | number | null | undefined): RodtepEntry | null {
	const ritc = normalizeRitc(ritcRaw);
	if (ritc.length !== 8) return null;
	return rodtep().get(ritc) ?? null;
}

/** The schedule's UQC spelling mapped onto the ICEGrid unit catalog. */
export function uqcToUnit(uqc: string): string | null {
	const key = uqc.trim().toLowerCase();
	if (key === 'kg' || key === 'kgs') return 'KGS';
	if (key === 'u' || key === 'nos' || key === 'no') return 'NOS';
	if (key === 'l' || key === 'ltr') return 'LTR';
	if (key === 'm' || key === 'mtr') return 'MTR';
	if (key === 'sqm') return 'SQM';
	if (key === 'cbm') return 'CBM';
	if (key === 'pcs') return 'PCS';
	if (key === 'set') return 'SET';
	if (key === 'tn' || key === 'ton') return 'TON';
	return null;
}
